using GraphApi.Models.VTS.Visitas;namespace GraphApi.Services.VTS.Visitas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Visitas.    /// </summary>    public interface IVisitasService    {        /// <summary>        /// Obtiene la lista de Visitas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadVisitas>> GetVisitas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Visitas con filtros opcionales.        /// </summary>        /// <param name="visitaID">Filtro opcional para VisitaID.</param>        /// <param name="visitanteNombre">Filtro opcional para VisitanteNombre.</param>        /// <param name="usuarioVisitadoID">Filtro opcional para UsuarioVisitadoID.</param>        /// <param name="casaID">Filtro opcional para CasaID.</param>        /// <param name="tipoIdentificacionID">Filtro opcional para TipoIdentificacionID.</param>        /// <param name="numeroIdentificacion">Filtro opcional para NumeroIdentificacion.</param>        /// <param name="rutaDocumento">Filtro opcional para RutaDocumento.</param>        /// <param name="fechaEntrada">Filtro opcional para FechaEntrada.</param>        /// <param name="fechaSalida">Filtro opcional para FechaSalida.</param>        /// <param name="autorizado">Filtro opcional para Autorizado.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetVisitasDynamic(            int? visitaID,            string? visitanteNombre,            int? usuarioVisitadoID,            int? casaID,            int? tipoIdentificacionID,            string? numeroIdentificacion,            string? rutaDocumento,            DateTime? fechaEntrada,            DateTime? fechaSalida,            bool? autorizado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Visita.        /// </summary>        /// <param name="objInput">Datos para crear el Visita.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadVisitas> CreateVisitas(            clCreateVisitas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Visita.        /// </summary>        /// <param name="objInput">Datos para actualizar el Visita, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadVisitas?> UpdateVisitas(            clUpdateVisitas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Visita por su ID.        /// </summary>        /// <param name="nVisitasID">ID del Visita a eliminar.</param>        Task<bool> DeleteVisitas(int nVisitasID);    }}